const retroStyle=document.createElement('link');retroStyle.rel='stylesheet';retroStyle.href='retro.css';document.head.append(retroStyle);
const PLAZA=L.latLng(-33.5100194,-70.756975);
const map=L.map('map',{zoomControl:false,minZoom:15,maxZoom:19}).setView(PLAZA,18);
map.attributionControl.setPrefix('');
map.attributionControl.addAttribution('Datos © <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>');
const world=L.layerGroup().addTo(map);
let fallback=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19}).addTo(map),lastQuery='',queryTimer,fetchController;
fallback.bringToBack();
const hint=document.querySelector('#hint'),place=document.querySelector('#place'),scoreEl=document.querySelector('#score'),toast=document.querySelector('#toast');
function show(msg){toast.textContent=msg;toast.classList.add('show');clearTimeout(show.t);show.t=setTimeout(()=>toast.classList.remove('show'),2200)}
function loadWorld(){clearTimeout(queryTimer);queryTimer=setTimeout(async()=>{let center=map.getCenter(),key=(Math.round(center.lat*300)/300)+','+(Math.round(center.lng*300)/300);if(key===lastQuery)return;lastQuery=key;const b=map.getBounds().pad(.25),box=[b.getSouth(),b.getWest(),b.getNorth(),b.getEast()].join(',');let query=`[out:json][timeout:20];(way["highway"](${box});way["building"](${box});way["leisure"="park"](${box});way["landuse"~"grass|forest|recreation_ground"](${box}););out geom;`;if(fetchController)fetchController.abort();fetchController=new AbortController();try{const res=await fetch('https://overpass-api.de/api/interpreter',{method:'POST',body:new URLSearchParams({data:query}),signal:fetchController.signal});if(!res.ok)throw Error('map');let data=await res.json();world.clearLayers();if(fallback){map.removeLayer(fallback);fallback=null}let ways=data.elements.filter(w=>w.geometry?.length>1);for(const w of ways.filter(w=>w.tags.leisure||w.tags.landuse)){L.polygon(w.geometry.map(p=>[p.lat,p.lon]),{color:'#568a55',weight:2,fillColor:'#7dc470',fillOpacity:1,interactive:false}).addTo(world)}for(const w of ways.filter(w=>w.tags.highway)){let p=w.geometry.map(p=>[p.lat,p.lon]);let major=/primary|secondary|tertiary/.test(w.tags.highway),wide=major?16:9;L.polyline(p,{color:'#9e9981',weight:wide+4,interactive:false}).addTo(world);L.polyline(p,{color:major?'#e9cf91':'#dfd3ae',weight:wide,interactive:false}).addTo(world)}for(const w of ways.filter(w=>w.tags.building)){L.polygon(w.geometry.map(p=>[p.lat,p.lon]),{color:'#745d56',weight:2,fillColor:'#c99076',fillOpacity:1,interactive:false}).addTo(world)}hint.textContent='Las calles y edificios representan datos reales. ¡Visita la plaza!'}catch(e){if(e.name==='AbortError')return;lastQuery='';if(!fallback){fallback=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19}).addTo(map);fallback.bringToBack()}hint.textContent='No se pudo cargar el mapa retro; mostrando el mapa normal.'}},700)}
map.on('moveend',loadWorld);
const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="32" height="42" viewBox="0 0 32 42" shape-rendering="crispEdges"><path fill="#29303a" d="M8 2h16v4h4v13h-3v12h-3v8h-6v-5h-2v5H8v-8H5V19H3V7h5z"/><path fill="#e14d42" d="M8 3h16v4h4v5H4V7h4z"/><path fill="#fff3d7" d="M7 12h18v9h-3v3H10v-3H7z"/><path fill="#192e38" d="M10 14h3v3h-3zm9 0h3v3h-3z"/><path fill="#4f91d1" d="M8 24h16v9h-5v-4h-6v4H8z"/><path fill="#efbf87" d="M5 22h3v7H5zm19 0h3v7h-3z"/></svg>`;
const playerIcon=L.divIcon({className:'',html:`<img class="sprite" src="data:image/svg+xml,${encodeURIComponent(svg)}" alt="">`,iconSize:[40,52],iconAnchor:[20,45]});
let pos=L.latLng(PLAZA.lat+.001,PLAZA.lng),player=L.marker(pos,{icon:playerIcon,interactive:false,zIndexOffset:1000}).addTo(map),started=true,timer=null,score=0;
const plazaIcon=L.divIcon({className:'',html:'<div class="plaza-mark">★<span>PLAZA DE MAIPÚ</span></div>',iconSize:[80,50],iconAnchor:[40,25]});
L.marker(PLAZA,{icon:plazaIcon,interactive:false}).addTo(map);
function update(){let d=Math.round(pos.distanceTo(PLAZA));place.textContent=d<60?'PLAZA DE MAIPÚ':'A '+d+' M DE PLAZA DE MAIPÚ';document.querySelector('#play').hidden=d>=60}
function start(latlng){pos=L.latLng(latlng);player.setLatLng(pos);map.setView(pos,18);update();loadWorld()}
function geolocate(){if(!navigator.geolocation){hint.textContent='Tu navegador no permite GPS.';return}hint.textContent='Buscando tu ubicación…';navigator.geolocation.getCurrentPosition(p=>start([p.coords.latitude,p.coords.longitude]),()=>{hint.textContent='No se pudo obtener tu ubicación. Prueba desde Maipú.'},{enableHighAccuracy:true,timeout:12000,maximumAge:60000})}
document.querySelector('#gps').addEventListener('click',geolocate);
document.querySelector('#reset').addEventListener('click',()=>start([PLAZA.lat+.001,PLAZA.lng]));
function move(dir){let step=5,lat=step/111320,lng=step/(111320*Math.cos(pos.lat*Math.PI/180));if(dir==='up')pos.lat+=lat;if(dir==='down')pos.lat-=lat;if(dir==='left')pos.lng-=lng;if(dir==='right')pos.lng+=lng;player.setLatLng(pos);map.panTo(pos,{animate:false});let img=document.querySelector('.sprite');if(img){img.classList.remove('walking');void img.offsetWidth;img.classList.add('walking');if(dir==='left')img.style.transform='scaleX(-1)';if(dir==='right')img.style.transform='scaleX(1)'}update()}
document.querySelectorAll('[data-dir]').forEach(b=>{let release=()=>{clearInterval(timer);timer=null};b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);move(b.dataset.dir);release();timer=setInterval(()=>move(b.dataset.dir),110)});b.addEventListener('pointerup',release);b.addEventListener('pointercancel',release);b.addEventListener('lostpointercapture',release)});
document.addEventListener('keydown',e=>{if(!document.querySelector('#modal').hidden)return;const dirs={ArrowUp:'up',ArrowDown:'down',ArrowLeft:'left',ArrowRight:'right',w:'up',s:'down',a:'left',d:'right'};if(dirs[e.key]){e.preventDefault();move(dirs[e.key])}});
const modal=document.querySelector('#modal'),board=document.querySelector('#board'),status=document.querySelector('#mini-status');let cards=[],flipped=[],busy=false,pairs=0;
function game(){cards=['🍎','🍎','⭐','⭐','🌻','🌻','🍒','🍒'].sort(()=>Math.random()-.5);flipped=[];busy=false;pairs=0;status.textContent='Encuentra las cuatro parejas.';board.innerHTML=cards.map((x,i)=>`<button class="memory" data-index="${i}" aria-label="Carta ${i+1}">?</button>`).join('');}
document.querySelector('#play').onclick=()=>{modal.hidden=false;game()};
document.querySelector('#close').onclick=()=>{modal.hidden=true};
document.querySelector('#again').onclick=game;
board.onclick=e=>{let b=e.target.closest('.memory');if(!b||busy||b.disabled||flipped.includes(b))return;let i=Number(b.dataset.index);b.textContent=cards[i];flipped.push(b);if(flipped.length===2){if(cards[Number(flipped[0].dataset.index)]===cards[i]){flipped.forEach(x=>x.disabled=true);flipped=[];pairs++;status.textContent=`Parejas: ${pairs}/4`;if(pairs===4){score++;scoreEl.textContent=score;status.textContent='¡Ganaste! Completaste todas las parejas.'}}else{busy=true;setTimeout(()=>{flipped.forEach(x=>x.textContent='?');flipped=[];busy=false},700)}}};
update();loadWorld();
